#include "EqProcessor.h"
namespace {
using SA=juce::AudioProcessorValueTreeState::SliderAttachment;using BA=juce::AudioProcessorValueTreeState::ButtonAttachment;using CA=juce::AudioProcessorValueTreeState::ComboBoxAttachment;
const juce::Colour colours[]{juce::Colour(0xff879fb8),juce::Colour(0xffe29a75),juce::Colour(0xffd6bc74),juce::Colour(0xff8cc59a),juce::Colour(0xff6cbfc8),juce::Colour(0xffaaa0dd),juce::Colour(0xffc28fb0)};
const char* names[]{"HIGH PASS","LOW","LOW MID","MID","HIGH MID","HIGH","LOW PASS"};
class EqGraph final:public juce::Component {
 EqProcessor& owner;int dragging=-1;float originY=0,originQ=1;
 juce::Rectangle<float> plot()const{return getLocalBounds().toFloat().reduced(42,24);}
 double highest()const{return std::min(20000.,owner.displayRate.load()*.475);}
 float xFor(double hz)const{const auto r=plot();return r.getX()+r.getWidth()*static_cast<float>(std::log(std::clamp(hz,20.,highest())/20)/std::log(highest()/20));}
 float yFor(double db)const{const auto r=plot();return r.getCentreY()-static_cast<float>(std::clamp(db,-24.,24.))*r.getHeight()/48;}
 double frequency(float x)const{const auto r=plot();return 20*std::pow(highest()/20,std::clamp((x-r.getX())/r.getWidth(),0.f,1.f));}
 juce::Point<float> node(int i)const{const auto b=owner.bands()[i];return {xFor(b.frequency),yFor(i==0||i==6?(b.kind==TracksmithEq::notch?-15:-3):b.gain)};}
 void gesture(bool begin){for(const char* key:{"freq","gain","q"})if(auto* p=owner.parameters.getParameter(EqProcessor::id(dragging,key))){if(begin)p->beginChangeGesture();else p->endChangeGesture();}}
public:
 int selected=3;EqGraph(EqProcessor& p):owner(p){setTooltipText();}
 void setTooltipText(){setMouseCursor(juce::MouseCursor::CrosshairCursor);}
 ~EqGraph()override{if(dragging>=0)gesture(false);}
 void paint(juce::Graphics& g)override{const auto r=plot();g.fillAll(juce::Colour(0xff141c25));g.setColour(juce::Colour(0xff233241));g.drawRoundedRectangle(r,5,1);
  for(double hz:{20.,50.,100.,200.,500.,1000.,2000.,5000.,10000.,20000.}){if(hz>highest())continue;const float x=xFor(hz);g.setColour(juce::Colour(0xff2a3846));g.drawVerticalLine(static_cast<int>(x),r.getY(),r.getBottom());g.setColour(juce::Colour(0xff92a5b7));g.setFont(juce::FontOptions(10));g.drawText(hz>=1000?juce::String(hz/1000,0)+"k":juce::String(hz,0),static_cast<int>(x)-20,static_cast<int>(r.getBottom())+5,40,14,juce::Justification::centred);}
  for(int db=-24;db<=24;db+=6){const float y=yFor(db);g.setColour(db==0?juce::Colour(0xff6f8395):juce::Colour(0xff2a3846));g.drawHorizontalLine(static_cast<int>(y),r.getX(),r.getRight());g.setColour(juce::Colour(0xff92a5b7));g.drawText((db>0?"+":"")+juce::String(db),0,static_cast<int>(y)-7,35,14,juce::Justification::centredRight);}
  const auto bands=owner.bands();const double rate=owner.displayRate.load();std::array<TracksmithEq::Design,7> filters;for(int b=0;b<7;++b)filters[b]=TracksmithEq::design(bands[b],rate);const bool bypass=owner.value("bypass")>.5f;
  for(int line=0;line<8;++line){juce::Path path;for(int px=0;px<=static_cast<int>(r.getWidth());px+=2){const float x=r.getX()+px;const auto hz=frequency(x);double magnitude=1;if(!bypass){if(line==7){for(int b=0;b<7;++b)if(bands[b].enabled)magnitude*=filters[b].magnitude(hz,rate);}else if(bands[line].enabled)magnitude=filters[line].magnitude(hz,rate);}const float y=yFor(20*std::log10(std::max(1.e-12,magnitude)));if(px==0)path.startNewSubPath(x,y);else path.lineTo(x,y);}g.setColour(line==7?juce::Colour(0xffd9eef3):colours[line].withAlpha(bands[line].enabled?.38f:.08f));g.strokePath(path,juce::PathStrokeType(line==7?2.f:1.f));}
  for(int b=0;b<7;++b){const auto point=node(b);g.setColour(colours[b].withAlpha(bands[b].enabled?1.f:.35f));g.fillEllipse(point.x-7,point.y-7,14,14);if(b==selected){g.setColour(juce::Colours::white);g.drawEllipse(point.x-10,point.y-10,20,20,1);}g.setColour(juce::Colour(0xff101720));g.setFont(juce::FontOptions(9,juce::Font::bold));g.drawText(juce::String(b+1),static_cast<int>(point.x)-7,static_cast<int>(point.y)-7,14,14,juce::Justification::centred);}
 }
 void mouseDown(const juce::MouseEvent& e)override{float distance=24;int found=-1;for(int b=0;b<7;++b){const float d=node(b).getDistanceFrom(e.position);if(d<distance){distance=d;found=b;}}if(found<0)return;selected=dragging=found;originY=e.position.y;originQ=static_cast<float>(owner.bands()[found].q);gesture(true);repaint();}
 void mouseDrag(const juce::MouseEvent& e)override{if(dragging<0)return;if(e.mods.isShiftDown())owner.change(EqProcessor::id(dragging,"q"),std::clamp(originQ*std::exp((originY-e.position.y)*.025f),.1f,18.f));else{owner.change(EqProcessor::id(dragging,"freq"),static_cast<float>(frequency(e.position.x)));if(dragging>0&&dragging<6)owner.change(EqProcessor::id(dragging,"gain"),std::clamp((plot().getCentreY()-e.position.y)*48/plot().getHeight(),-18.f,18.f));}repaint();}
 void mouseUp(const juce::MouseEvent&)override{if(dragging>=0)gesture(false);dragging=-1;}
 void mouseDoubleClick(const juce::MouseEvent& e)override{for(int b=0;b<7;++b)if(node(b).getDistanceFrom(e.position)<20){auto* p=owner.parameters.getParameter(EqProcessor::id(b,"enabled"));p->beginChangeGesture();p->setValueNotifyingHost(p->getValue()>.5f?0:1);p->endChangeGesture();break;}}
 void mouseWheelMove(const juce::MouseEvent& e,const juce::MouseWheelDetails& wheel)override{int hit=selected;for(int b=0;b<7;++b)if(node(b).getDistanceFrom(e.position)<20){hit=b;break;}auto* p=owner.parameters.getParameter(EqProcessor::id(hit,"q"));p->beginChangeGesture();owner.change(EqProcessor::id(hit,"q"),static_cast<float>(std::clamp(owner.bands()[hit].q*std::exp(wheel.deltaY*2),.1,18.)));p->endChangeGesture();}
};
class BandPanel final:public juce::Component {
 EqProcessor& owner;int index;juce::ToggleButton enabled;juce::ComboBox type,slope;juce::Slider frequency,gain,q;std::unique_ptr<BA> enableLink;std::unique_ptr<CA> typeLink,slopeLink;std::unique_ptr<SA> freqLink,gainLink,qLink;
 void slider(juce::Slider& control,const char* key,const juce::String& suffix){control.setSliderStyle(juce::Slider::RotaryHorizontalVerticalDrag);control.setTextBoxStyle(juce::Slider::TextBoxBelow,false,118,20);control.setTextValueSuffix(suffix);control.setColour(juce::Slider::rotarySliderFillColourId,colours[index]);control.setColour(juce::Slider::textBoxBackgroundColourId,juce::Colour(0xff101821));control.setColour(juce::Slider::textBoxOutlineColourId,juce::Colour(0xff304152));control.setDoubleClickReturnValue(true,owner.parameters.getParameter(EqProcessor::id(index,key))->convertFrom0to1(owner.parameters.getParameter(EqProcessor::id(index,key))->getDefaultValue()));control.setTooltip("Double-click to reset. Type a value below the knob.");addAndMakeVisible(control);}
public:
 BandPanel(EqProcessor& p,int b):owner(p),index(b){enabled.setButtonText(names[b]);enabled.setColour(juce::ToggleButton::textColourId,colours[b]);addAndMakeVisible(enabled);enableLink=std::make_unique<BA>(p.parameters,EqProcessor::id(b,"enabled"),enabled);slider(frequency,"freq"," Hz");slider(q,"q","");freqLink=std::make_unique<SA>(p.parameters,EqProcessor::id(b,"freq"),frequency);qLink=std::make_unique<SA>(p.parameters,EqProcessor::id(b,"q"),q);
  if(b>0&&b<6){slider(gain,"gain"," dB");gainLink=std::make_unique<SA>(p.parameters,EqProcessor::id(b,"gain"),gain);}
  if(b==0||b==6){type.addItem(b==0?"High pass":"Low pass",1);type.addItem("Notch",2);slope.addItemList({"6 dB/oct","12 dB/oct","18 dB/oct","24 dB/oct"},1);addAndMakeVisible(slope);slopeLink=std::make_unique<CA>(p.parameters,EqProcessor::id(b,"slope"),slope);}
  if(b==1||b==5){type.addItem(b==1?"Low shelf":"High shelf",1);type.addItem("Bell",2);}if(type.getNumItems()){addAndMakeVisible(type);typeLink=std::make_unique<CA>(p.parameters,EqProcessor::id(b,"mode"),type);}
 }
 void refresh(){const bool pass=(index==0||index==6)&&owner.value(EqProcessor::id(index,"mode"))<.5f;q.setEnabled(!pass);slope.setEnabled(pass);}
 void paint(juce::Graphics& g)override{g.setColour(juce::Colour(0xff1b2733));g.fillRoundedRectangle(getLocalBounds().toFloat().reduced(2),7);g.setColour(colours[index].withAlpha(.65f));g.fillRect(12,0,getWidth()-24,2);g.setColour(juce::Colour(0xff9badbc));g.setFont(juce::FontOptions(10));g.drawText("FREQUENCY",0,62,getWidth(),16,juce::Justification::centred);g.drawText(index==0||index==6?"FILTER SLOPE":"GAIN",0,164,getWidth(),16,juce::Justification::centred);g.drawText("Q / WIDTH",0,263,getWidth(),16,juce::Justification::centred);if(!type.getNumItems())g.drawText("Bell",10,33,getWidth()-20,22,juce::Justification::centred);}
 void resized()override{const int w=getWidth();enabled.setBounds(10,8,w-20,22);type.setBounds(12,33,w-24,23);frequency.setBounds(12,79,w-24,81);gain.setBounds(12,181,w-24,78);slope.setBounds(12,197,w-24,26);q.setBounds(12,280,w-24,75);}
};
class EqEditor final:public juce::AudioProcessorEditor,private juce::Timer {
 EqProcessor& owner;juce::LookAndFeel_V4 look;EqGraph graph;std::array<std::unique_ptr<BandPanel>,7> panels;juce::Slider input,output;juce::ToggleButton bypass,phase;juce::TextButton flat;std::unique_ptr<SA> inLink,outLink;std::unique_ptr<BA> bypassLink,phaseLink;juce::TooltipWindow tips{this,600};float inLevel=0,outLevel=0;
public:
 EqEditor(EqProcessor& p):AudioProcessorEditor(p),owner(p),graph(p){look.setColour(juce::ResizableWindow::backgroundColourId,juce::Colour(0xff101821));look.setColour(juce::ComboBox::backgroundColourId,juce::Colour(0xff101821));look.setColour(juce::ComboBox::outlineColourId,juce::Colour(0xff3a4b5b));setLookAndFeel(&look);addAndMakeVisible(graph);for(int b=0;b<7;++b){panels[b]=std::make_unique<BandPanel>(p,b);addAndMakeVisible(*panels[b]);panels[b]->refresh();}
  for(auto* slider:{&input,&output}){slider->setSliderStyle(juce::Slider::LinearHorizontal);slider->setTextBoxStyle(juce::Slider::TextBoxBelow,false,96,18);slider->setTextValueSuffix(" dB");slider->setDoubleClickReturnValue(true,0);slider->setColour(juce::Slider::trackColourId,juce::Colour(0xff82bfc8));addAndMakeVisible(slider);}inLink=std::make_unique<SA>(p.parameters,"input",input);outLink=std::make_unique<SA>(p.parameters,"output",output);bypass.setButtonText("Bypass");phase.setButtonText("Polarity invert");flat.setButtonText("Reset flat");addAndMakeVisible(bypass);addAndMakeVisible(phase);addAndMakeVisible(flat);bypassLink=std::make_unique<BA>(p.parameters,"bypass",bypass);phaseLink=std::make_unique<BA>(p.parameters,"invert",phase);flat.onClick=[this]{for(auto* parameter:owner.getParameters()){parameter->beginChangeGesture();parameter->setValueNotifyingHost(parameter->getDefaultValue());parameter->endChangeGesture();}};owner.inputPeak=0;owner.outputPeak=0;setSize(1120,760);startTimerHz(30);
 }
 ~EqEditor()override{stopTimer();setLookAndFeel(nullptr);}
 void paint(juce::Graphics& g)override{g.fillAll(juce::Colour(0xff101821));g.setColour(juce::Colour(0xffecf2f6));g.setFont(juce::FontOptions(24,juce::Font::bold));g.drawText("TRACKSMITH",22,13,270,30,juce::Justification::centredLeft);g.setColour(juce::Colour(0xff86c0c9));g.setFont(juce::FontOptions(13));g.drawText("EQ 7  /  PARAMETRIC EQUALIZER",24,44,300,22,juce::Justification::centredLeft);g.setFont(juce::FontOptions(10));g.setColour(juce::Colour(0xffa8bac9));g.drawText("INPUT",330,10,130,16,juce::Justification::centred);g.drawText("OUTPUT",485,10,130,16,juce::Justification::centred);g.drawText("Drag dots: frequency / gain     Shift-drag or wheel: Q     Double-click dots: band on/off",24,318,820,18,juce::Justification::centredLeft);g.drawText("Zero latency  |  Mono / stereo  |  +/-18 dB bands",24,733,650,18,juce::Justification::centredLeft);meter(g,inLevel,650,"IN");meter(g,outLevel,705,"OUT");}
 void meter(juce::Graphics& g,float level,int x,const juce::String& label){const float db=juce::Decibels::gainToDecibels(level,-90.f);g.setColour(juce::Colour(0xff283947));g.fillRoundedRectangle(static_cast<float>(x),14,8,47,2);const float height=47*juce::jlimit(0.f,1.f,(db+60)/60);g.setColour(db>=0?juce::Colour(0xffeb827f):juce::Colour(0xff83c3ad));g.fillRoundedRectangle(static_cast<float>(x),61-height,8,height,2);g.setFont(juce::FontOptions(9));g.drawText(label,x-12,65,35,12,juce::Justification::centred);g.drawText(db<=-89?"-inf":juce::String(db,1),x+13,30,37,16,juce::Justification::centredLeft);}
 void resized()override{input.setBounds(325,28,140,43);output.setBounds(480,28,140,43);bypass.setBounds(790,14,100,25);phase.setBounds(790,44,110,25);flat.setBounds(970,25,120,28);graph.setBounds(18,85,1084,230);for(int b=0;b<7;++b)panels[b]->setBounds(18+b*155,350,154,370);}
 void timerCallback()override{inLevel=std::max(owner.inputPeak.exchange(0),inLevel*.87f);outLevel=std::max(owner.outputPeak.exchange(0),outLevel*.87f);for(auto& panel:panels)panel->refresh();graph.repaint();repaint(640,0,140,82);}
};
}
juce::AudioProcessorEditor* EqProcessor::createEditor(){return new EqEditor(*this);}
